// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // allow this contract to accept ether sent back by c.withdraw
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e27);

        // fund c through its payable fallback
        vm.deal(address(this), amount);
        (bool funded, ) = address(c).call{value: amount}("");
        assertTrue(funded);

        uint256 balBefore = address(c).balance;
        assertTrue(balBefore >= amount);

        // owner is address(this) (deployer in setUp); drive the mutated entry
        vm.prank(address(this));
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: withdraw(amount) either reverts (leaving the balance
        // untouched) or succeeds and the contract's balance drops by exactly
        // `amount`. The mutant transfers 0, so a successful call leaves the
        // balance unchanged.
        assertTrue(!ok || (address(c).balance == balBefore - amount));
    }
}
